CREATE DATABASE PHARMA;
USE PHARMA;
CREATE TABLE demo (
    primaryid BIGINT NOT NULL,
    caseid BIGINT NOT NULL,
    case_version INTEGER,
    age VARCHAR(20),
    age_cod VARCHAR(20),
    sex VARCHAR(20),
    wt_kg VARCHAR(20),
    event_dt VARCHAR(20),
    rept_dt VARCHAR(20),
    occr_country VARCHAR(50),
    reporter_occupation VARCHAR(50)
);











    
CREATE TABLE drug (
    primaryid BIGINT NOT NULL,
    drug_seq INTEGER NOT NULL,
    drugname VARCHAR(255) NOT NULL,
    role_cod VARCHAR(10) NOT NULL,
    route VARCHAR(50),
    dose_amt VARCHAR(20),
    dose_unit VARCHAR(20),
    dechal VARCHAR(5),
    rechal VARCHAR(5)
);




















    
CREATE TABLE indi (
    primaryid BIGINT NOT NULL,
    indi_pt VARCHAR(255) NOT NULL
);














    
CREATE TABLE outc (
    primaryid BIGINT NOT NULL,
    outc_cod VARCHAR(10) NOT NULL
);









    
CREATE TABLE reac (
    primaryid BIGINT NOT NULL,
    pt VARCHAR(255) NOT NULL,
    drug_rec_act VARCHAR(10)
);

















